<div class="admin-page-head"><h1>کالکشن محصولات</h1><?= CHtml::link('بازگشت',array('adminCollection/index'),array('class'=>'btn btn-outline')) ?></div>
<?php if($error): ?><div class="flash flash-error"><?= CHtml::encode($error) ?></div><?php endif; ?>
<?php $form=$this->beginWidget('CActiveForm'); ?><?= $form->errorSummary($model) ?><section class="panel"><div class="form-row"><div class="field"><label>عنوان *</label><?= $form->textField($model,'title',array('required'=>true)) ?></div><div class="field"><label>آدرس انگلیسی</label><?= $form->textField($model,'slug',array('dir'=>'ltr')) ?></div></div><div class="field"><label>توضیحات</label><?= $form->textArea($model,'description',array('class'=>'markdown-editor','rows'=>5)) ?></div><div class="check-field"><?= $form->checkBox($model,'is_active') ?><label>فعال و قابل نمایش</label></div><?php $this->widget('MediaPicker',array('name'=>'image_id','value'=>CmsMedia::ids($model->image),'multiple'=>false)); ?></section>
<section class="panel"><h2>انتخاب محصولات و ترتیب نمایش</h2><p class="muted">عدد کوچک‌تر زودتر نمایش داده می‌شود. محصولات پیش‌نویس در سایت نمایش داده نمی‌شوند.</p><input type="search" data-filter-products placeholder="فیلتر نام و شناسه کالا…" aria-label="فیلتر محصولات"><div class="table-wrap"><table class="data-table"><thead><tr><th>انتخاب</th><th>محصول</th><th>ترتیب</th></tr></thead><tbody><?php foreach($products as $p): $position=array_search($p->id,$selected); ?><tr data-product-choice><td><?= CHtml::checkBox('products[]',$position!==false,array('value'=>$p->id,'aria-label'=>$p->title)) ?></td><td><?= CHtml::encode($p->title.' · '.$p->sku) ?></td><td><?= CHtml::numberField('positions['.$p->id.']',$position===false?100:$position,array('min'=>0,'max'=>9999,'aria-label'=>'ترتیب '.$p->title)) ?></td></tr><?php endforeach; ?></tbody></table></div><?= CHtml::submitButton('ذخیره کالکشن',array('class'=>'btn btn-primary')) ?></section><?php $this->endWidget(); ?>
<?php if(!$model->isNewRecord): ?><?= CHtml::beginForm(array('adminCollection/delete','id'=>$model->id),'post',array('data-confirm'=>'کالکشن حذف شود؟')) ?><?= CHtml::submitButton('حذف کالکشن',array('class'=>'btn btn-danger')) ?><?= CHtml::endForm() ?><?php endif; ?>
